void same(const old::Result&a,const old::Result&b){need(a.complete==b.complete&&a.row_changed==b.row_changed&&a.retry_available==b.retry_available&&a.corrector_scope_entered==b.corrector_scope_entered&&a.error==b.error&&a.baseline_error==b.baseline_error&&a.baseline_rows_written==b.baseline_rows_written&&a.baseline_violation==b.baseline_violation,"legacy base outcome");const auto&x=a.retry;const auto&y=b.retry;need(x.complete==y.complete&&x.changed==y.changed&&x.error==y.error&&x.epsilon==y.epsilon&&x.initial_violation==y.initial_violation&&x.interval_lower==y.interval_lower&&x.interval_upper==y.interval_upper&&x.row_bounds_written==y.row_bounds_written&&bits(x.seed,y.seed)&&bits(x.row_direction_bounds,y.row_direction_bounds)&&x.attempts.size()==y.attempts.size(),"legacy uniform result exact");need(a.corrections.size()==b.corrections.size(),"legacy correction count");for(std::size_t i=0;i<a.corrections.size();++i){const auto&c=a.corrections[i];const auto&d=b.corrections[i];need(c.iteration==d.iteration&&c.row==d.row&&c.error==d.error&&bits(c.delta,d.delta),"legacy correction vector exact");}}
