 legacy=old::prepare(A,lo,hi,x,D);modern=fresh::prepare(A,lo,hi,x,D);need(!legacy.complete&&legacy.error=="bounded initializer ray has no interior; wholepolytope unknown"&&legacy.corrections.size()==8&&modern.global_scope_eligible&&!modern.global_scope_entered&&modern.global_scans.empty(),"shared8 exhausted, no reset");same(legacy,modern);
 // Existing flat prefix stays intact while new work uses only the remainder.
 A=Eigen::MatrixXd::Zero(3,144);A(0,23)=1;A(0,31)=-1;for(int j=7;j<144;j+=8)A(1,j)=1;A(2,7)=1;lo=Eigen::VectorXd::Constant(3,-1);hi=Eigen::VectorXd::Ones(3);lo(0)=2e-12;lo(1)=8e-11;hi(2)=1e-12;
 legacy=old::prepare(A,lo,hi,x,D);modern=fresh::prepare(A,lo,hi,x,D);need(legacy.corrections.size()==1&&modern.legacy_corrections_count==1&&modern.complete&&modern.corrections.size()<=8&&bits(legacy.corrections[0].delta,modern.corrections[0].delta),"legacy applied prefix exact plus shared remainder");
 lo(1)=2e-10;auto large=fresh::prepare(A,lo,hi,x,D);need(!large.complete&&large.global_scope_entered&&!large.corrections.back().applied&&!large.corrections.back().delta_available&&!large.corrections.back().error.empty(),"original1e-10 eligibility not expanded, failed proposal metadata retained");
 A=Eigen::MatrixXd::Zero(1,144);A(0,0)=1;lo=Eigen::VectorXd::Constant(1,2e-12);hi=Eigen::VectorXd::Ones(1);legacy=old::prepare(A,lo,hi,x,D);modern=fresh::prepare(A,lo,hi,x,D);need(!modern.global_scope_entered,"no fallback outside nointerior");same(legacy,modern);D(0)=0;legacy=old::prepare(A,lo,hi,x,D);modern=fresh::prepare(A,lo,hi,x,D);same(legacy,modern);need(!modern.global_scope_entered,"invalidscale remains old refusal");

